/* PDF and DXF writers for the primitives produced by Drawing. Both are generated by hand,
   so the editor stays free of libraries; text is limited to Latin-1, one byte per character. */
const Export=(()=>{
  const MM_TO_PT=72/25.4,ARC_STEPS=16,MARGIN_MM=10,TITLE_MM=22,FIT_PADDING_M=.4;
  const PAPERS={A4:[297,210],A3:[420,297],A2:[594,420]};
  const SCALES=[10,20,25,30,40,50,75,100,125,150,200,250,300,400,500,1000];
  const LINE_MM={WALLS:.35,OPENINGS:.25,STAIRS:.18,FURNITURE:.13,ROOMS:.13,DIMENSIONS:.13};
  const GRAY={WALLS:.15,STAIRS:.2,FURNITURE:.4,DIMENSIONS:.3,ROOMS:.1,OPENINGS:0};
  const CUSTOM_GRAY=.2,CUSTOM_LINE_MM=.2;
const DXF_COLORS={WALLS:7,OPENINGS:1,STAIRS:5,FURNITURE:8,ROOMS:3,DIMENSIONS:4};

  const latin1=text=>String(text).replace(/[^\x00-\xff]/g,'?');
  const toBytes=text=>{const out=new Uint8Array(text.length);for(let i=0;i<text.length;i++)out[i]=text.charCodeAt(i)&255;return out;};
  const fixed=(n,digits=3)=>(+n.toFixed(digits)).toString();

  // picks sheet orientation and the largest standard scale that fits the drawing
  function sheet(prims,{paper='A3',scale='auto',orientation='auto'}={}){
    const box=Drawing.bounds(prims)||{x0:0,x1:1,z0:0,z1:1};
    const wM=box.x1-box.x0+2*FIT_PADDING_M,hM=box.z1-box.z0+2*FIT_PADDING_M;
    const[long,short]=PAPERS[paper]||PAPERS.A3;
    const fit=(w,h)=>{
      const usableW=w-2*MARGIN_MM,usableH=h-2*MARGIN_MM-TITLE_MM;
      return SCALES.find(den=>wM*1000/den<=usableW&&hM*1000/den<=usableH)||SCALES[SCALES.length-1];
    };
    const landscape={w:long,h:short,den:fit(long,short)},portrait={w:short,h:long,den:fit(short,long)};
    let pick=orientation==='portrait'?portrait:orientation==='landscape'?landscape:(portrait.den<landscape.den?portrait:landscape);
    if(scale!=='auto')pick={...pick,den:+scale};
    return{...pick,box,paper,orientation:pick.w>pick.h?'landscape':'portrait',fits:wM*1000/pick.den<=pick.w-2*MARGIN_MM&&hM*1000/pick.den<=pick.h-2*MARGIN_MM-TITLE_MM};
  }

  /* ---------- PDF ---------- */
  const HELV_WIDTH=text=>[...text].reduce((w,ch)=>w+(/[A-ZÁÉÍÓÚÑ×]/.test(ch)?.68:/[ilj.,:;|' ]/.test(ch)?.28:/[mwMW]/.test(ch)?.85:.52),0);

  function pdf(prims,meta,options){
    const s=sheet(prims,options),k=MM_TO_PT*1000/s.den;                      // points per metre of the plan
    const pageW=s.w*MM_TO_PT,pageH=s.h*MM_TO_PT;
    const usableW=(s.w-2*MARGIN_MM)*MM_TO_PT,usableH=(s.h-2*MARGIN_MM-TITLE_MM)*MM_TO_PT;
    const drawW=(s.box.x1-s.box.x0)*k,drawH=(s.box.z1-s.box.z0)*k;
    const ox=MARGIN_MM*MM_TO_PT+(usableW-drawW)/2-s.box.x0*k;
    const oy=(MARGIN_MM+TITLE_MM)*MM_TO_PT+(usableH-drawH)/2+s.box.z1*k;
    const X=x=>fixed(ox+x*k,2),Y=z=>fixed(oy-z*k,2);
    const ops=[];
    const color=(g,stroke)=>ops.push(`${g} ${g} ${g} ${stroke?'RG':'rg'}`);
    const width=mm=>ops.push(`${fixed(mm*MM_TO_PT,2)} w`);
    const text=(value,x,y,mm,{bold=false,center=false,gray=0}={})=>{
      const t=latin1(value).replace(/([\\()])/g,'\\$1'),size=mm*MM_TO_PT,shift=center?HELV_WIDTH(value)*size/2:0;
      ops.push('BT',`${gray} g`,`/${bold?'F2':'F1'} ${fixed(size,2)} Tf`,`${fixed(x-shift,2)} ${fixed(y,2)} Td`,`(${t}) Tj`,'ET');
    };
    const path=(pts,close)=>{ops.push(`${X(pts[0][0])} ${Y(pts[0][1])} m`);for(const[x,z]of pts.slice(1))ops.push(`${X(x)} ${Y(z)} l`);if(close)ops.push('h');};

    // paper frame and drawing, walls first so their fill sits under doors and furniture
    ops.push('q');width(.35);color(0,true);
    ops.push(`${fixed(MARGIN_MM*MM_TO_PT,2)} ${fixed(MARGIN_MM*MM_TO_PT,2)} ${fixed(pageW-2*MARGIN_MM*MM_TO_PT,2)} ${fixed(pageH-2*MARGIN_MM*MM_TO_PT,2)} re S`);
    ops.push(`${fixed(MARGIN_MM*MM_TO_PT,2)} ${fixed((MARGIN_MM+TITLE_MM)*MM_TO_PT,2)} m ${fixed(pageW-MARGIN_MM*MM_TO_PT,2)} ${fixed((MARGIN_MM+TITLE_MM)*MM_TO_PT,2)} l S`);
    const base=['WALLS','FURNITURE','STAIRS','ROOMS','OPENINGS','DIMENSIONS'],order=[...base,...new Set(prims.map(p=>p.layer).filter(l=>!base.includes(l)))];
    for(const layer of order){
      for(const p of prims.filter(p=>p.layer===layer)){
        ops.push('q');color(GRAY[layer]??CUSTOM_GRAY,true);width(LINE_MM[layer]||CUSTOM_LINE_MM);
        if(p.t==='poly'){
          path(p.pts,true);
          if(p.fill==='wall'){color(GRAY.WALLS,false);ops.push('B');}else ops.push('S');
        }else if(p.t==='line'){path([[p.x1,p.z1],[p.x2,p.z2]],false);ops.push('S');}
        else if(p.t==='arc'){
          const pts=Array.from({length:ARC_STEPS+1},(_,i)=>{const a=(p.a0+(p.a1-p.a0)*i/ARC_STEPS)*Math.PI/180;return[p.cx+p.r*Math.cos(a),p.cz+p.r*Math.sin(a)];});
          path(pts,false);ops.push('S');
        }else if(p.t==='text')text(p.text,ox+p.x*k,oy-p.z*k,p.mm,{bold:p.bold,center:true,gray:GRAY[layer]??CUSTOM_GRAY});
        ops.push('Q');
      }
    }

    // title block
    const left=(MARGIN_MM+3)*MM_TO_PT,bottom=MARGIN_MM*MM_TO_PT;
    text(latin1(meta.name||'Plano'),left,bottom+TITLE_MM*MM_TO_PT-7*MM_TO_PT,5,{bold:true});
    text(`Escala 1:${s.den}   ·   Hoja ${s.paper} ${s.orientation==='landscape'?'horizontal':'vertical'}   ·   Medidas en metros`,left,bottom+8*MM_TO_PT,2.8);
    text(`${meta.date||''}   ·   Blueprint Sketch`,left,bottom+3*MM_TO_PT,2.4,{gray:.4});
    ops.push('Q');

    const stream=ops.join('\n');
    const objects=[
      '<< /Type /Catalog /Pages 2 0 R >>',
      '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
      `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${fixed(pageW,2)} ${fixed(pageH,2)}] /Contents 4 0 R /Resources << /Font << /F1 5 0 R /F2 6 0 R >> >> >>`,
      `<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`,
      '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>',
      '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>'
    ];
    let body='%PDF-1.4\n';
    const offsets=objects.map((o,i)=>{const at=body.length;body+=`${i+1} 0 obj\n${o}\nendobj\n`;return at;});
    const xref=body.length;
    body+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`+offsets.map(o=>`${String(o).padStart(10,'0')} 00000 n \n`).join('');
    body+=`trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
    return{bytes:toBytes(body),sheet:s};
  }

  /* ---------- DXF (R12, millimetres, y up) ---------- */
  function dxf(prims,meta,options){
    const den=options&&options.scale&&options.scale!=='auto'?+options.scale:sheet(prims,options).den;
    const out=[];
    const pair=(code,value)=>out.push(String(code),String(value));
    const mm=n=>fixed(n*1000,3);
    const colors={...DXF_COLORS};
    for(const p of prims)if(!(p.layer in colors))colors[p.layer]=p.aci||7;
    const layers=Object.keys(colors);
    pair(0,'SECTION');pair(2,'HEADER');pair(9,'$ACADVER');pair(1,'AC1009');pair(9,'$DWGCODEPAGE');pair(3,'ANSI_1252');pair(0,'ENDSEC');
    pair(0,'SECTION');pair(2,'TABLES');pair(0,'TABLE');pair(2,'LAYER');pair(70,layers.length);
    for(const name of layers){pair(0,'LAYER');pair(2,name);pair(70,0);pair(62,colors[name]);pair(6,'CONTINUOUS');}
    pair(0,'ENDTAB');pair(0,'ENDSEC');
    pair(0,'SECTION');pair(2,'ENTITIES');
    for(const p of prims){
      if(p.t==='line'){pair(0,'LINE');pair(8,p.layer);pair(10,mm(p.x1));pair(20,mm(-p.z1));pair(30,0);pair(11,mm(p.x2));pair(21,mm(-p.z2));pair(31,0);}
      else if(p.t==='poly'){
        pair(0,'POLYLINE');pair(8,p.layer);pair(66,1);pair(70,p.closed?1:0);
        for(const[x,z]of p.pts){pair(0,'VERTEX');pair(8,p.layer);pair(10,mm(x));pair(20,mm(-z));pair(30,0);}
        pair(0,'SEQEND');pair(8,p.layer);
      }else if(p.t==='arc'){
        // the plan is y-down, DXF is y-up: angles mirror and the arc runs counter-clockwise
        pair(0,'ARC');pair(8,p.layer);pair(10,mm(p.cx));pair(20,mm(-p.cz));pair(30,0);pair(40,mm(p.r));pair(50,fixed(((-p.a1)%360+360)%360,3));pair(51,fixed(((-p.a0)%360+360)%360,3));
      }else if(p.t==='text'){
        pair(0,'TEXT');pair(8,p.layer);pair(10,mm(p.x));pair(20,mm(-p.z));pair(30,0);pair(40,fixed(p.mm*den,2));pair(1,latin1(p.text));
        pair(72,1);pair(73,2);pair(11,mm(p.x));pair(21,mm(-p.z));pair(31,0);
      }
    }
    pair(0,'ENDSEC');pair(0,'EOF');
    return{bytes:toBytes(out.join('\r\n')+'\r\n'),den};
  }

  return{sheet,pdf,dxf,PAPERS,SCALES};
})();
if(typeof module!=='undefined')module.exports=Export;
